INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-way-up', 'east', 'the-ramp-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plain', 'north', 'the-north-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-shelf', 'south', 'the-under-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-top', 'east', 'the-red-tail', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ramp-head', 'door', 'The Ramp Head', 'The ramp levels out and the ground you are standing on is warm through your boots. Not sunlit — warm, on its own account, on the shaded side of a mountain, at a height where the shade has not been above freezing in a century. Everything about this is wrong and none of it is dangerous, which is worse.', 0, 0, 'mountain', 0, 110, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'north', 'the-glazed-slab', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'south', 'the-warm-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'east', 'the-black-glass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'west', 'the-way-up', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-glazed-slab', 'door', 'The Glazed Slab', 'A slab of rock with a surface like a cracked pot glaze, black-brown, shining, catching the light in a way stone does not. Frost has not touched it. Run a hand over it and it is smooth in ropes and runs, as though it was liquid and stopped being liquid quickly, and the ropes all run the same way, downhill.', 0, 0, 'mountain', 0, 110, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'north', 'the-first-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'south', 'the-ramp-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'east', 'the-run-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warm-flags', 'door', 'The Warm Flags', 'Flat rock laid like paving, dry and warm and swept clear of the grit that is over everything else at this height. Lying down on it you would be comfortable for the first time since the shore. Nothing is lying on it. Nothing on this mountain sleeps here, and there is no reason for that you can see.', 0, 0, 'mountain', 0, 110, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'north', 'the-ramp-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'south', 'the-warm-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'east', 'the-heat-shimmer', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-glass', 'door', 'The Black Glass', 'Where the glaze is thickest it has gone properly to glass: black, conchoidal, breaking to an edge sharper than any blade anybody ever ground. There are chips of it lying loose. A person could arm themselves out of this room in a minute and it would cut anything on this mountain and shatter on the second stroke.', 0, 0, 'mountain', 0, 111, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'north', 'the-run-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'south', 'the-heat-shimmer', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'east', 'the-scald', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'west', 'the-ramp-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-run-stone', 'door', 'The Run Stone', 'Rock that ran downhill and set again in lobes with the front edges still curled over, the way cooling honey stops. It is a shape nothing else on this mountain has and the whole of the rest of the mountain is broken instead. Something did this in one afternoon; the frost has been at the ordinary rock for ten thousand years and only ever made gravel.', 0, 0, 'mountain', 0, 111, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'north', 'the-shoulder-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'south', 'the-black-glass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'west', 'the-glazed-slab', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-heat-shimmer', 'door', 'The Heat Shimmer', 'The air over this ground shakes. Looking across it, the terraces beyond are unreliable — they lift and swim and settle, and things standing on them appear to move when they have not. It is impossible to judge distance through it and impossible to be certain of anything you see.', 0, 0, 'mountain', 0, 111, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'north', 'the-black-glass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'south', 'the-heat-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'east', 'the-basking-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'west', 'the-warm-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scald', 'door', 'The Scald', 'A patch of ground fifty feet across where the rock is scorched pale and everything in it is cracked into small flakes that lift and rock underfoot. The pattern of it has an edge — sharp, curved, as though the heat came from one place and stopped where it stopped. Standing at the edge you can put one boot on either side of it.', 0, 0, 'mountain', 0, 112, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scald', 'south', 'the-basking-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scald', 'west', 'the-black-glass', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-basking-flags', 'door', 'The Basking Flags', 'Warm flat stone, and on it, arranged with a great deal of care and no interest in you whatever, adders. Adders, at this height, above the snow line, in country where a cold-blooded thing should have died out four tiers down. They are here because the rock is warm and the rock is warm for a reason nothing on this hillside will explain.', 0, 0, 'mountain', 0, 112, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'north', 'the-scald', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'south', 'the-sun-trap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'east', 'the-crack-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'west', 'the-heat-shimmer', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crack-line', 'door', 'The Crack Line', 'A crack running the width of the ground, a hand across, with warm air coming steadily out of it and the rock either side dry when everything else at this height is wet. Grass grows along the lip of it — actual grass, green, in a line, four tiers above the last of it.', 0, 0, 'mountain', 0, 113, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'south', 'the-warm-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'east', 'the-adder-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'west', 'the-basking-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-adder-shelf', 'door', 'The Adder Shelf', 'A shelf of broken warm rock with holes in it going back further than an arm, and it is full. You cannot see them all and there is no way to count them. They are not aggressive and they do not need to be: there is nowhere to put a foot here that is more than a stride from one.', 0, 0, 'mountain', 0, 114, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'south', 'the-thin-crack', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'east', 'the-first-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'west', 'the-crack-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sun-trap', 'door', 'The Sun Trap', 'A bowl of rock that holds the day''s heat and adds it to whatever the ground is already doing, so the air in here is genuinely hot and smells of dry stone and, faintly, of something that has been dead for a while somewhere close.', 0, 0, 'mountain', 0, 112, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'north', 'the-basking-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'south', 'the-vent', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'east', 'the-warm-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'west', 'the-heat-under', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warm-scree', 'door', 'The Warm Scree', 'Loose stone that is warm all the way down — dig into it with a boot and the stones two hands deep are warmer than the ones on top. Things have been lying in it. There are body-shaped hollows scooped out of the scree, a dozen of them, and none of them is the shape of anything you have met.', 0, 0, 'mountain', 0, 113, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'north', 'the-crack-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'south', 'the-under-warmth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'east', 'the-thin-crack', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'west', 'the-sun-trap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thin-crack', 'door', 'The Thin Crack', 'A crack too narrow to enter, breathing out warm air with a faint reek in it, and around the mouth of it the rock is stained a pale yellow-white in a crust you can crumble between finger and thumb. It smells of struck matches. It is not a smell this world has anywhere else.', 0, 0, 'mountain', 0, 114, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'north', 'the-adder-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'south', 'the-dry-heat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'east', 'the-drag-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'west', 'the-warm-scree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-vent', 'door', 'The Vent', 'A hole in the rock the width of a barrel with warm dry air coming steadily up out of it, and a floor of clean sand round the mouth, out of the wind, out of the weather, and warm all night. It is the most comfortable place on this mountain by a very long way. Nothing follows you in here, and there is nothing in here to follow.', 0, 1, 'mountain', 0, 112, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'north', 'the-sun-trap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'east', 'the-under-warmth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'west', 'the-lower-warm', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-under-warmth', 'door', 'The Under-Warmth', 'Ground that steams gently on a cold morning across its whole width, in threads, out of a hundred small cracks. From the tier below this whole hillside would look like it was burning. There is nobody on the tier below to see it.', 0, 0, 'mountain', 0, 113, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'north', 'the-warm-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'east', 'the-dry-heat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'west', 'the-vent', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dry-heat', 'door', 'The Dry Heat', 'Bone dry, dusty, and hot enough that the sweat is off you before it forms. There is a scatter of small bones here, all of them cracked open lengthwise, and they are dry the way nothing at this altitude gets to be dry: not weathered, baked.', 0, 0, 'mountain', 0, 114, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'north', 'the-thin-crack', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'south', 'the-under-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'east', 'the-tallow-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'west', 'the-under-warmth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-terrace', 'door', 'The First Terrace', 'A level shelf a hundred feet across, and on it a red deer hind, opened along the belly, most of her still there and nothing yet at her. She did not walk up here. There is no route to this shelf that a deer could take, and the ground where she is lying has no drag mark leading onto it from any direction at all.', 0, 0, 'mountain', 0, 115, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'north', 'the-eyrie-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'south', 'the-drag-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'east', 'the-second-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'west', 'the-adder-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-terrace', 'door', 'The Second Terrace', 'The same again, and used far longer: the rock is stained black in patches that go down into the stone, and the stains are layered, and the layers are years. Something has been bringing things to this exact shelf since before anybody alive was born.', 0, 0, 'mountain', 0, 116, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'south', 'the-scatter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'east', 'the-third-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'west', 'the-first-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-third-terrace', 'door', 'The Third Terrace', 'Bones by the hundred, sorted by nothing, from every animal on this mountain and several you cannot place. Among them, twice, the long bones of something that had to have stood taller than a horse, and there is nothing that size in this country and has not been for a very long time.', 0, 0, 'mountain', 0, 117, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'south', 'the-gorge-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'east', 'the-last-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'west', 'the-second-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-terrace', 'door', 'The Last Terrace', 'The end of the shelves, and the cleanest of them — swept, or as near swept as makes no difference, with the bones pushed to the edges in a bank and the middle of it bare. Something keeps this floor clear. The wind here comes from one direction and this has been cleared from all of them.', 0, 0, 'mountain', 0, 118, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-terrace', 'south', 'the-picked-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-terrace', 'west', 'the-third-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drag-mark', 'door', 'The Drag Mark', 'A groove worn into the rock, two feet wide, polished, running from the edge of the terrace above out and away over the lip and into open air. Things have been pulled along it, many times, and every one of them was pulled the same way: not up onto the shelf, and not down off it. Off the edge, into nothing.', 0, 0, 'mountain', 0, 115, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'north', 'the-first-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'south', 'the-tallow-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'east', 'the-scatter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'west', 'the-thin-crack', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scatter', 'door', 'The Scatter', 'Where the terrace above sheds what it does not want, over the lip and down, so that this ground is deep in hide, hair, hooves and the ends of things. Everything on this tier that eats works this room at some hour of the day, and they take each other''s turn without much argument, because there is more here than any of them can finish.', 0, 0, 'mountain', 0, 116, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'north', 'the-second-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'east', 'the-gorge-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'west', 'the-drag-mark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gorge-ground', 'door', 'The Gorge Ground', 'Flat, open, and covered in birds, and they do not go up as you come in — they shuffle sideways, keeping the distance they have decided on, and go back to it. There are enough of them that the noise is constant and the smell arrives before you do.', 0, 0, 'mountain', 0, 117, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'north', 'the-third-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'east', 'the-picked-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'west', 'the-scatter', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-picked-ground', 'door', 'The Picked Ground', 'What is left when the birds have had a day at it: skeletons in their proper order, absolutely clean, lying where they lay. It is very quiet in here compared with the room next door. There is nothing left on any of this and everything knows it.', 0, 0, 'mountain', 0, 118, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'north', 'the-last-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'south', 'the-white-heap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'west', 'the-gorge-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tallow-stone', 'door', 'The Tallow Stone', 'A boulder with fat rendered into its surface over years until the stone itself has gone waxy and yellow and takes a thumbprint. It is the one thing up here that has got richer rather than poorer. Insects work it in the warm hours, in a haze, and there is nothing else at this height for them to be doing.', 0, 0, 'mountain', 0, 115, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'north', 'the-drag-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'east', 'the-grease-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'west', 'the-dry-heat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grease-flat', 'door', 'The Grease Flat', 'Rock gone dark and slick underfoot, treacherous in a way wet rock is not — it does not dry, and it does not wash off, and a boot goes out from under you on it without any warning at all. The whole floor slopes gently towards the drop.', 0, 0, 'mountain', 0, 116, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grease-flat', 'east', 'the-crack-heap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grease-flat', 'west', 'the-tallow-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crack-heap', 'door', 'The Crack Heap', 'A heap of bones every one of which has been split lengthwise and emptied — a season''s work, in one place, done by something with the patience to carry each one up and drop it on the same rock. The rock is under the heap and is white with it.', 0, 0, 'mountain', 0, 117, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-heap', 'east', 'the-white-heap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-heap', 'west', 'the-grease-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-white-heap', 'door', 'The White Heap', 'The oldest of the leavings, gone chalky and light and blowing away a little more each year, heaped against the foot of the wall in a bank you would take for snow from any distance. It is not snow. It has been building here for a great deal longer than the snow has been going.', 0, 0, 'mountain', 0, 118, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-heap', 'north', 'the-picked-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-heap', 'west', 'the-crack-heap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eyrie-foot', 'door', 'The Eyrie Foot', 'The bottom of a face that has ledges on it all the way up, every one of them white, every one of them used. Bones lie thick along the base where they have been dropped from above over years. The scale of what is up there is the thing you notice: these are not small ledges and they are not carrying small birds.', 0, 0, 'mountain', 0, 115, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'north', 'the-guano-face', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'south', 'the-first-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'east', 'the-eyrie-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eyrie-ledge', 'door', 'The Eyrie Ledge', 'A ledge wide enough for four people to stand abreast, and on it a nest — a platform of sticks and bone six feet across, packed and trodden and built up in layers for so many seasons that the bottom of it has gone to peat. There is a bird on it and the bird is not the size of anything that should be able to build this.', 0, 0, 'mountain', 0, 116, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'north', 'the-white-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'east', 'the-nest-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'west', 'the-eyrie-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-nest-shelf', 'door', 'The Nest Shelf', 'Three more of them along the same shelf, all in use, all filthy, all enormous, and the noise from the young in them carries the length of the tier and does not stop. Anything walking along this ledge is walking past four sets of parents at the range of a raised arm.', 0, 0, 'mountain', 0, 117, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'north', 'the-updraught', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'east', 'the-eyrie-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'west', 'the-eyrie-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eyrie-head', 'door', 'The Eyrie Head', 'The end of the ledge system, and the biggest nest of all — abandoned, older than the rest by a long way, and built to a size that the birds on the shelves below could not manage between them. Whatever raised young in this was not a vulture. Nothing has been in it for decades and nothing has taken it over either.', 0, 0, 'mountain', 0, 118, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-head', 'north', 'the-lookout', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-head', 'west', 'the-nest-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-guano-face', 'door', 'The Guano Face', 'The wall below the ledges, white from top to bottom and streaked in runnels, and it stinks in a way that makes your eyes water within a minute. Nothing grows on it. It is the only surface on this mountain that has been comprehensively ruined by living things, and it took them centuries.', 0, 0, 'mountain', 0, 115, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-face', 'south', 'the-eyrie-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-face', 'east', 'the-white-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-white-wall', 'door', 'The White Wall', 'Sheer, white, and the one line of holds up it goes straight through the middle, which means climbing it with your face six inches from the worst of it. At the top the ground opens out onto the perches. Everything with wings takes the other route.', 0, 0, 'mountain', 0, 116, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'north', 'the-high-perch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'south', 'the-eyrie-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'east', 'the-updraught', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'west', 'the-guano-face', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-updraught', 'door', 'The Updraught', 'Air comes up this section of face all day, steadily, hard enough to lift a coat, and the birds use it: they drop off the ledges above, take it, and are two hundred feet higher without a wingbeat. Standing here you get the whole smell of the eyrie delivered continuously.', 0, 0, 'mountain', 0, 117, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'south', 'the-nest-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'east', 'the-lookout', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'west', 'the-white-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lookout', 'door', 'The Lookout', 'The corner of the face, with a view down the whole east side of the mountain and out over ground no map in this world covers. There is always a bird on this corner. It is never the same bird twice and it is never not there.', 0, 0, 'mountain', 0, 118, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lookout', 'south', 'the-eyrie-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lookout', 'west', 'the-updraught', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-perch', 'door', 'The High Perch', 'A knuckle of rock above the eyrie, worn smooth on top and white round the base, where the big ones sit out the middle of the day with their wings half open. It is worn smooth because so many of them have sat here. There is room on it for two and there are usually two.', 0, 0, 'mountain', 0, 116, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'north', 'the-swept-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'south', 'the-white-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'east', 'the-wind-post', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wind-post', 'door', 'The Wind Post', 'A pillar standing off the ridge with a flat top and a permanent wind over it, and the top is scoured clean of everything, including the white. Nothing perches here. It faces the threshold and everything that ever tried to sit on it has decided against it.', 0, 0, 'mountain', 0, 117, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-post', 'north', 'the-ash-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-post', 'west', 'the-high-perch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-step', 'door', 'The First Step', 'The ridge starts again here, going east in a series of steps, and the rock changes under your hand within a stride: cold, ordinary, frost-shattered, exactly like the whole mountain below and nothing at all like the ground you have just come off.', 0, 0, 'mountain', 0, 110, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'south', 'the-glazed-slab', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'east', 'the-shoulder-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'west', 'the-lee-side', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shoulder-stone', 'door', 'The Shoulder Stone', 'A hump of rock on the crest with a hollow worn in the top of it that holds water after rain, and the water is the last drinkable thing on the mountain. Everything up here comes to this hollow. The ground round it is beaten to dust by feet in five different sizes.', 0, 0, 'mountain', 0, 111, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'north', 'the-north-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'south', 'the-run-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'east', 'the-tower-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'west', 'the-first-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tower-foot', 'door', 'The Tower Foot', 'The foot of the first tower, which stands off the crest like a chimney and is climbed round rather than over, on a ledge that goes anticlockwise and is out of sight of everything for most of its length. Things wait on this ledge. There are droppings on it that are not old.', 0, 0, 'mountain', 0, 112, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'north', 'the-cold-side', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'east', 'the-black-tower', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'west', 'the-shoulder-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-tower', 'door', 'The Black Tower', 'A tower of rock gone black on the east face only — not glazed, not run, just burnt, in a hard-edged shadow-shape as though something extremely bright had stood beside it once and gone away again. The west face is grey and ordinary and lichened like any other rock in the world.', 0, 0, 'mountain', 0, 113, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'north', 'the-shadow-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'east', 'the-tower-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'west', 'the-tower-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tower-gap', 'door', 'The Tower Gap', 'The gap between the last two towers, floored with rubble and roofed with sky, and the wind funnels through it hard enough that you go through leaning. On the far side the ground rises to the notch and the notch is the only way east from here.', 0, 0, 'mountain', 0, 114, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-gap', 'north', 'the-high-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-gap', 'west', 'the-black-tower', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-north-lip', 'door', 'The North Lip', 'The north edge of the crest, where the ground goes over into shadow and stays there. There is old ice in the cracks along the whole lip. Fifty paces south of here the rock is warm enough to sleep on; standing on this line you can feel both at once.', 0, 0, 'mountain', 0, 111, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'north', 'the-crest-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'south', 'the-shoulder-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'east', 'the-cold-side', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-side', 'door', 'The Cold Side', 'Permanently shaded ground, hard frozen, with rime standing on the north face of every stone. Nothing lives on this strip and nothing crosses it if there is any other way round, which there is, forty feet south, and everything knows it.', 0, 0, 'mountain', 0, 112, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'north', 'the-crown-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'south', 'the-tower-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'east', 'the-shadow-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'west', 'the-north-lip', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shadow-step', 'door', 'The Shadow Step', 'A step down into shade so total that after the glare off the crest you stand still for a while and wait for your eyes. Everything in here is grey and blue and cold. There are things standing in it. There always are, because it is the one piece of cover between the towers and the notch.', 0, 0, 'mountain', 0, 113, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'north', 'the-last-crest', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'south', 'the-black-tower', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'east', 'the-high-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'west', 'the-cold-side', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-notch', 'door', 'The High Notch', 'The last gap in the ridge, narrow, floored in scoured rock, and it looks east onto the threshold. From here you can see the whole of the empty ground and the door at the far end of it and everything else on the ridge behind you, and nothing at all in between.', 0, 0, 'mountain', 0, 114, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'south', 'the-tower-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'east', 'the-scorched-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'west', 'the-shadow-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crown-edge', 'door', 'The Crown Edge', 'The north brow of the ridge, level and exposed, with the whole world laid out below on that side: the cloud line under you like a floor, and the sea somewhere past the edge of it, and no ground anywhere in sight that is higher than this except what is behind you.', 0, 0, 'mountain', 0, 112, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'south', 'the-cold-side', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'east', 'the-last-crest', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'west', 'the-crest-gap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-crest', 'door', 'The Last Crest', 'The end of the ridge proper, a heap of shattered blocks with nothing beyond them but the drop and the threshold ground away to the east. The blocks are cracked in the way frost cracks things, and one of them is cracked in a way frost does not: through, cleanly, and the two halves are eighteen feet apart.', 0, 0, 'mountain', 0, 113, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-crest', 'south', 'the-shadow-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-crest', 'west', 'the-crown-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scorched-step', 'door', 'The Scorched Step', 'Through the notch and onto ground that is different immediately: pale, cracked shallow, and swept clean of every loose thing. There is nothing living here. Not a bird, not a print, not a dropping, and after four tiers of a mountain busy with animals the absence has a shape and an edge and you are standing on it.', 0, 0, 'mountain', 0, 115, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'north', 'the-quiet-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'east', 'the-swept-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'west', 'the-high-notch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-swept-terrace', 'door', 'The Swept Terrace', 'A terrace of bare rock, wide and level and blown clear — except the wind at this height comes from one direction, and this ground has been cleared from all of them, and the loose stone is heaped round the edges in a rough ring as though something large had settled here and turned round more than once.', 0, 0, 'mountain', 0, 116, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'north', 'the-bare-place', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'south', 'the-high-perch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'east', 'the-ash-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'west', 'the-scorched-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ash-ground', 'door', 'The Ash Ground', 'Grey-white grit lying over the rock, fine as flour, and it takes a print perfectly and holds it. There are no prints. Yours are the first and they will be the only ones. Nothing on this mountain has walked across this room since the last time it rained here.', 0, 0, 'mountain', 0, 117, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'north', 'the-threshold', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'south', 'the-wind-post', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'east', 'the-hot-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'west', 'the-swept-terrace', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hot-flags', 'door', 'The Hot Flags', 'The end of the terrace, and the flags here are hot — not warm; hot enough that you would not sit down on them and not so hot that you cannot stand. The heat is coming up through the rock from underneath, evenly, across the whole floor, and it is not coming from the sun because it is exactly the same after dark.', 0, 0, 'mountain', 0, 118, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-flags', 'west', 'the-ash-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quiet-ground', 'door', 'The Quiet Ground', 'Bare rock, no wind in it despite the height, and no sound of any kind. On a mountain there is always something — grit moving, water somewhere, a bird a mile off — and here there is not, and the silence is not peaceful. It is the silence of a room that everything has left.', 0, 0, 'mountain', 0, 115, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-ground', 'south', 'the-scorched-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-ground', 'east', 'the-bare-place', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bare-place', 'door', 'The Bare Place', 'Flat stone, entirely clean, and warm. Standing in the middle of it you are the largest thing in sight and the most exposed you have been anywhere in this world. It is a hundred paces to any cover in any direction and the cover is behind you.', 0, 0, 'mountain', 0, 116, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'south', 'the-swept-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'east', 'the-threshold', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'west', 'the-quiet-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-threshold', 'door', 'The Threshold', 'The ground narrows between two walls of rock into an approach forty feet wide, floored in the same swept ash and rising gently east. There is a smell here, strong, and it is the smell of the crack-line four hundred paces back multiplied by a very great deal: struck matches, hot stone, and something underneath that is meat.', 0, 0, 'mountain', 0, 117, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'south', 'the-ash-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'east', 'the-last-shelter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'west', 'the-bare-place', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-shelter', 'door', 'The Last Shelter', 'A hole under a fallen block, dry, dark, and just big enough, with a floor of clean grit and a view east through the gap of a slot of pale sky. It is warm in here and out of the wind and nothing follows you in. It is also thirty feet from ground nothing on this mountain will set foot on, and both of those things are true at once.', 0, 1, 'mountain', 0, 118, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelter', 'east', 'the-summit-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelter', 'west', 'the-threshold', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-summit-gate', 'door', 'The Summit Gate', 'The approach ends at a wall of rock with a gap in it, and the gap is the way through, and beyond it there is nothing to see but light. Warm air comes out steadily. The ground at the gap is swept absolutely clean and the sweeping stops in a line you could draw with a ruler, and on this side of the line the grit is undisturbed for as far back as you can see.', 0, 0, 'mountain', 0, 119, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-gate', 'west', 'the-last-shelter', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-red-tail', 'door', 'The Red Tail', 'The red ground runs out in a tail of rust-coloured grit that thins to nothing across a hundred paces, and the rock under it goes grey, then dark, then warm. It is the gentlest way onto this tier and the longest, and everything that walks up here rather than flying takes it.', 0, 0, 'mountain', 0, 107, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-tail', 'east', 'the-low-traverse', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-tail', 'west', 'the-gully-top', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-low-traverse', 'door', 'The Low Traverse', 'A shelf running east under the whole south side, level and easy, with the tier''s business going on somewhere above you and out of sight. It is the only ground on this mountain where you can walk for a while and think about something else, and that is exactly what makes it worth being careful on.', 0, 0, 'mountain', 0, 108, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-traverse', 'east', 'the-south-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-traverse', 'west', 'the-red-tail', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-south-shelf', 'door', 'The South Shelf', 'The shelf widens and there are dwarf plants growing along the back of it in a strip, brown and woody and barely alive, watered by something seeping out of the rock behind. It is the last growing thing on the mountain and it covers about the area of a table.', 0, 0, 'mountain', 0, 109, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shelf', 'east', 'the-warm-gutter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shelf', 'west', 'the-low-traverse', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warm-gutter', 'door', 'The Warm Gutter', 'A gutter of smooth rock carrying warm air rather than water, running the length of the shelf, and the grit in it is dry and fine and full of prints going both ways. Every animal on this tier uses this and none of them is trying to hide the fact.', 0, 0, 'mountain', 0, 110, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gutter', 'east', 'the-lower-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gutter', 'west', 'the-south-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lower-flags', 'door', 'The Lower Flags', 'Flat warm paving under an overhang, out of the weather and out of the sight of anything above. Things have lain here: hollows, hair, and in one place the whole print of something that was here long enough for its warmth to have dried the grit under it.', 0, 0, 'mountain', 0, 111, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-flags', 'east', 'the-south-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-flags', 'west', 'the-warm-gutter', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-south-step', 'door', 'The South Step', 'The shelf ends against a step of solid rock the height of two people, split by a chimney you can get up with your back on one side and your boots on the other. Everything on four legs stops here. It is the reason the low traverse is quiet and the ground above it is not.', 0, 0, 'mountain', 0, 112, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'north', 'the-step-up', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'east', 'the-south-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'west', 'the-lower-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-step-up', 'door', 'The Step Up', 'The top of the chimney, on a ledge with the terraces'' noise suddenly close and the whole warm side of the tier opening out east. Coming up here you arrive in the middle of everything with no warning at all and no way to look first.', 0, 0, 'mountain', 0, 112, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-up', 'south', 'the-south-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-up', 'east', 'the-terrace-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-south-gully', 'door', 'The South Gully', 'A gully running up into the terraces, choked with loose stone and everything that has been washed or dropped down it, and it is the drain for the whole kill ground above. What is in it is not pleasant and there is a great deal of it.', 0, 0, 'mountain', 0, 113, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-gully', 'north', 'the-terrace-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-gully', 'west', 'the-south-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-terrace-foot', 'door', 'The Terrace Foot', 'The foot of the terrace wall, in the shade of it, with bones lying about that came off the top and a strip of clear ground along the base that everything uses as a road. It is the only shade on the warm side and everything up here spends part of its day in it.', 0, 0, 'mountain', 0, 113, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'south', 'the-south-gully', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'east', 'the-under-terrace', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'west', 'the-step-up', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-under-terrace', 'door', 'The Under-Terrace', 'Under the lip of the terraces proper, where what falls off them lands and stays, and it is deep. You are walking on it rather than over it. Something has dug into the pile in three places and dug down a long way, and the diggings are recent.', 0, 0, 'mountain', 0, 114, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-terrace', 'north', 'the-dry-heat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-terrace', 'west', 'the-terrace-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-north-step', 'door', 'The North Step', 'Up off the cold plain onto the north shoulder of the last ridge, and the wind arrives the moment you top the step and does not let up again. The rock here is ordinary and cold and there is nothing warm anywhere on this side.', 0, 0, 'mountain', 0, 107, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-step', 'south', 'the-cold-plain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-step', 'east', 'the-cold-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-shoulder', 'door', 'The Cold Shoulder', 'A broad cold shoulder of frost-shattered rock with rime standing on the north side of everything, and the sun does not reach it at any hour. It is the coldest ground on the mountain and it is four hundred paces from the warmest.', 0, 0, 'mountain', 0, 108, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shoulder', 'east', 'the-shoulder-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shoulder', 'west', 'the-north-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shoulder-end', 'door', 'The Shoulder End', 'The shoulder narrows and ends against the crest, with a choice of going up onto it or dropping into the lee on the south side. From here the ridge ahead is in profile, tower after tower, and you can count them and know exactly how long the rest of this is going to take.', 0, 0, 'mountain', 0, 109, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'north', 'the-north-crest', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'south', 'the-lee-side', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'west', 'the-cold-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lee-side', 'door', 'The Lee Side', 'A hollow in the south side of the shoulder, out of the wind entirely, floored with dry grit and walled on three sides — the last ordinary shelter on this mountain, the kind a cold hillside makes anywhere in the world. Nothing follows you in. It is not warm and there is nothing strange about it, and after the ground east of here that is worth something.', 0, 1, 'mountain', 0, 109, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-side', 'north', 'the-shoulder-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-side', 'east', 'the-first-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-north-crest', 'door', 'The North Crest', 'On top of the crest, in the full weight of the wind, with the north face dropping away on your left into cloud that is a long way below you now. The crest runs east in a clean line. There is nothing to hold on to for its whole length and nothing that needs holding on to unless it is blowing, and it is blowing.', 0, 0, 'mountain', 0, 109, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-crest', 'south', 'the-shoulder-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-crest', 'east', 'the-crest-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crest-walk', 'door', 'The Crest Walk', 'Level walking on a crest three paces wide, which after everything below it is nearly pleasant. The rock is scoured, the wind is steady, and you can see the towers ahead and the eyrie beyond them and, past all of it, the pale ground at the end that has nothing on it.', 0, 0, 'mountain', 0, 110, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-walk', 'east', 'the-crest-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-walk', 'west', 'the-north-crest', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crest-gap', 'door', 'The Crest Gap', 'A break in the crest where the rock has fallen away on both sides at once, leaving a saddle you go down into and up out of. There is old snow in the bottom of it, grey and hard, and it is the last snow on this mountain — everything east of here is either cold rock or warm rock and there is none of it left.', 0, 0, 'mountain', 0, 111, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'south', 'the-north-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'east', 'the-crown-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'west', 'the-crest-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-under-step', 'door', 'The Under-Step', 'Down off the shelves and in under the whole east side, on a line that runs below everything. It is dark in here for the height, with the tier hanging over you, and the first thing you notice is that the rock has stopped being cold.', 0, 0, 'mountain', 0, 108, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-step', 'north', 'the-under-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-step', 'east', 'the-shelf-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shelf-walk', 'door', 'The Shelf Walk', 'A walk under the overhang, floored in dry grit, roofed by rock, with the light coming in from the side in a long strip. Bones lie along the back wall where things have carried them in to work on them out of sight of the birds.', 0, 0, 'mountain', 0, 109, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-walk', 'east', 'the-warm-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-walk', 'west', 'the-under-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warm-under', 'door', 'The Warm Under', 'The rock overhead is warm and the ground is warm and the air is still, and it smells of dust and animals. Things sleep here. There are hollows worn in the grit in a row along the back, all of them used, and none of them belonging to anything small.', 0, 0, 'mountain', 0, 110, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'north', 'the-warm-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'east', 'the-heat-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'west', 'the-shelf-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-heat-under', 'door', 'The Heat Under', 'Where the overhang narrows and the warmth concentrates, and it is properly hot: dry, still, and thick. It is unpleasant to be in for long and it is full of things that are not finding it unpleasant at all.', 0, 0, 'mountain', 0, 111, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'north', 'the-heat-shimmer', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'south', 'the-lower-warm', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'east', 'the-sun-trap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'west', 'the-warm-under', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lower-warm', 'door', 'The Lower Warm', 'The low corner of the warm ground, where it runs out over the edge and the cold comes back up at you from below. Standing on the line you have warm air on your face and cold air round your knees and the whole of the tier below laid out under the second of them.', 0, 0, 'mountain', 0, 111, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-warm', 'north', 'the-heat-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-warm', 'east', 'the-vent', NULL);
